from typing import List

def factorize(n: int) -> List[int]:
    factors = []
    # Handle the case for 0 and 1
    if n <= 1:
        return factors
    # Check for smallest prime factor
    while n % 2 == 0:
        factors.append(2)
        n //= 2
    # Check for odd factors
    for i in range(3, int(n**0.5) + 1, 2):
        while n % i == 0:
            factors.append(i)
            n //= i
    # If n is a prime number greater than 2
    if n > 2:
        factors.append(n)
    return factors

