import heapq

def minPath(grid, k):
    N = len(grid)
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]

    def is_valid(x, y):
        return 0 <= x < N and 0 <= y < N

    def dijkstra(start_x, start_y):
        pq = [(0, start_x, start_y, [grid[start_x][start_y]])]
        visited = set((start_x, start_y))

        while pq:
            _, x, y, path = heapq.heappop(pq)

            if len(path) == k:
                return path

            for dx, dy in directions:
                nx, ny = x + dx, y + dy
                if is_valid(nx, ny) and (nx, ny) not in visited:
                    visited.add((nx, ny))
                    heapq.heappush(pq, (grid[nx][ny], nx, ny, path + [grid[nx][ny]]))

        return None

    min_path = None
    for i in range(N):
        for j in range(N):
            path = dijkstra(i, j)
            if path and (min_path is None or path < min_path):
                min_path = path

    return min_path

